-- ═══════════════════════════════════════════════════════════════════════════════
-- InnVolt ERP · Fase 11: sistema profesional de levantamientos técnicos
--   · Plantillas con código único, versión, estado (borrador / activa / archivada),
--     descripción, objetivo del levantamiento e instrucciones para el técnico.
--   · Las plantillas anteriores quedan ARCHIVADAS (no se borran: los informes ya llenados
--     guardan su propia copia y no cambian).
--   · Informes de la visita: código y versión de la plantilla usada, objetivo, y trazabilidad
--     (quién lo creó, quién lo modificó por última vez y quién lo completó).
--   · Catálogo inicial: 13 plantillas de levantamiento (una por tipo de servicio) y un acta
--     de entrega. Se generan con scripts/plantillas_levantamiento.py; si ya existen (por
--     código), NO se sobrescriben: lo que se edite en la app se respeta.
-- Ejecutar DESPUÉS de las fases 1 a 10. Es idempotente y no borra datos.
-- ═══════════════════════════════════════════════════════════════════════════════

-- ─── 1. Plantillas: código, versión, estado y textos ─────────────────────────
ALTER TABLE public.informe_plantillas ADD COLUMN IF NOT EXISTS codigo        TEXT;
ALTER TABLE public.informe_plantillas ADD COLUMN IF NOT EXISTS version       INT  NOT NULL DEFAULT 1;
ALTER TABLE public.informe_plantillas ADD COLUMN IF NOT EXISTS estado        TEXT NOT NULL DEFAULT 'activa';
ALTER TABLE public.informe_plantillas ADD COLUMN IF NOT EXISTS descripcion   TEXT;
ALTER TABLE public.informe_plantillas ADD COLUMN IF NOT EXISTS objetivo      TEXT;
ALTER TABLE public.informe_plantillas ADD COLUMN IF NOT EXISTS instrucciones TEXT;
ALTER TABLE public.informe_plantillas DROP CONSTRAINT IF EXISTS informe_plantillas_estado_check;
ALTER TABLE public.informe_plantillas ADD CONSTRAINT informe_plantillas_estado_check CHECK (estado IN ('borrador','activa','archivada'));
CREATE UNIQUE INDEX IF NOT EXISTS uq_informe_plantillas_codigo ON public.informe_plantillas(codigo) WHERE codigo IS NOT NULL;

-- «activa» (la de antes) sigue al estado: solo las activas se pueden elegir.
CREATE OR REPLACE FUNCTION public.informe_plantilla_estado()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.estado IS NOT DISTINCT FROM OLD.estado AND NEW.activa IS DISTINCT FROM OLD.activa THEN
    NEW.estado := CASE WHEN NEW.activa THEN 'activa' ELSE 'archivada' END;   -- clientes viejos que solo cambian «activa»
  END IF;
  NEW.activa := NEW.estado = 'activa';
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS trg_informe_plantilla_estado ON public.informe_plantillas;
CREATE TRIGGER trg_informe_plantilla_estado BEFORE INSERT OR UPDATE ON public.informe_plantillas
  FOR EACH ROW EXECUTE FUNCTION public.informe_plantilla_estado();

-- Las plantillas anteriores (sin código) quedan archivadas.
UPDATE public.informe_plantillas SET estado = 'archivada' WHERE codigo IS NULL AND estado <> 'archivada';

-- ─── 2. Informes de la visita: versión usada y trazabilidad ──────────────────
ALTER TABLE public.informes_visita ADD COLUMN IF NOT EXISTS plantilla_codigo  TEXT;
ALTER TABLE public.informes_visita ADD COLUMN IF NOT EXISTS plantilla_version INT;
ALTER TABLE public.informes_visita ADD COLUMN IF NOT EXISTS objetivo          TEXT;
ALTER TABLE public.informes_visita ADD COLUMN IF NOT EXISTS instrucciones     TEXT;
ALTER TABLE public.informes_visita ADD COLUMN IF NOT EXISTS modificado_por    UUID REFERENCES public.profiles(id) ON DELETE SET NULL;
ALTER TABLE public.informes_visita ADD COLUMN IF NOT EXISTS completado_por    UUID REFERENCES public.profiles(id) ON DELETE SET NULL;

CREATE OR REPLACE FUNCTION public.informe_visita_estado()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE a public.agendamientos;
BEGIN
  IF TG_OP = 'UPDATE' AND auth.uid() IS NOT NULL THEN NEW.modificado_por := auth.uid(); END IF;
  IF NEW.estado = 'completado' AND (TG_OP = 'INSERT' OR OLD.estado IS DISTINCT FROM 'completado') THEN
    NEW.completado_at := COALESCE(NEW.completado_at, NOW());
    NEW.completado_por := COALESCE(auth.uid(), NEW.completado_por);
    SELECT * INTO a FROM public.agendamientos WHERE id = NEW.agendamiento_id;
    PERFORM public.notificar('agenda.ver', 'informe_visita',
      'Informe listo: ' || left(COALESCE(NEW.plantilla_nombre, 'Informe de visita'), 70),
      left(COALESCE(a.titulo, ''), 90) || ' · ' || to_char(a.fecha, 'DD-MM'), '/visita/' || NEW.agendamiento_id);
  ELSIF NEW.estado = 'borrador' THEN
    NEW.completado_at := NULL; NEW.completado_por := NULL;
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS trg_informe_visita_estado ON public.informes_visita;
CREATE TRIGGER trg_informe_visita_estado BEFORE INSERT OR UPDATE ON public.informes_visita
  FOR EACH ROW EXECUTE FUNCTION public.informe_visita_estado();

