INSERT INTO public.informe_plantillas (codigo, nombre, tipo, tipo_servicio, descripcion, objetivo, instrucciones, intro, campos, checklist, estado, version)
VALUES ($t$ACTA-ENT$t$, $t$Acta de entrega de trabajos$t$, $t$entrega$t$, NULL, $t$Recepción del trabajo terminado, con pruebas y firma del cliente.$t$,
  $t$Dejar constancia de lo ejecutado, las pruebas realizadas y la recepción conforme.$t$, $t$Detalla lo ejecutado y las pruebas. Separa lo ejecutado de lo recomendado o pendiente.$t$, $t$Acta de entrega de los trabajos ejecutados.$t$,
  $j$[{"clave": "s_ejecutado", "etiqueta": "Trabajos ejecutados", "tipo": "seccion"}, {"clave": "ejecutados", "etiqueta": "Trabajo ejecutado", "tipo": "lista", "subcampos": [{"clave": "descripcion", "etiqueta": "Trabajo", "tipo": "texto"}, {"clave": "ubicacion", "etiqueta": "Ubicación", "tipo": "texto"}, {"clave": "cantidad", "etiqueta": "Cantidad", "tipo": "numero"}, {"clave": "unidad", "etiqueta": "Unidad", "tipo": "seleccion", "opciones": ["un", "m", "m²", "punto", "circuito", "global", "hora"]}]}, {"clave": "s_pruebas", "etiqueta": "Pruebas y mediciones", "tipo": "seccion"}, {"clave": "pruebas", "etiqueta": "Pruebas realizadas", "tipo": "multiseleccion", "opciones": ["Continuidad", "Aislación", "Prueba de diferenciales", "Resistencia de tierra", "Funcionamiento con el cliente", "Configuración entregada"]}, {"clave": "mediciones", "etiqueta": "Medición", "tipo": "lista", "subcampos": [{"clave": "punto", "etiqueta": "Punto", "tipo": "texto"}, {"clave": "magnitud", "etiqueta": "Magnitud", "tipo": "texto"}, {"clave": "valor", "etiqueta": "Valor", "tipo": "numero"}, {"clave": "resultado", "etiqueta": "Resultado", "tipo": "seleccion", "opciones": ["Normal", "Fuera de rango"]}], "naturaleza": "medido", "alerta": ["Fuera de rango"]}, {"clave": "s_entrega", "etiqueta": "Entrega", "tipo": "seccion"}, {"clave": "garantia", "etiqueta": "Garantía", "tipo": "texto"}, {"clave": "recomendaciones", "etiqueta": "Recomendaciones de uso y mantención", "tipo": "parrafo"}, {"clave": "pendientes", "etiqueta": "Pendientes", "tipo": "parrafo", "cotizacion": ["pendiente"]}]$j$::JSONB,
  $j$[{"texto": "Se probaron las protecciones"}, {"texto": "Se entregó la instalación limpia"}, {"texto": "Se explicó el funcionamiento al cliente"}]$j$::JSONB, 'activa', 1)
ON CONFLICT (codigo) WHERE codigo IS NOT NULL DO NOTHING;
-- @@FIN@@

-- ─── 4. Ajuste (si la fase 11 ya se había corrido) ───────────────────────────
-- «Motivo de la visita» llega prellenado con lo que pidió el cliente. Solo agrega esa marca
-- a la pregunta «motivo»; no cambia nada más de la plantilla.
UPDATE public.informe_plantillas p
   SET campos = (SELECT jsonb_agg(CASE WHEN e->>'clave' = 'motivo' THEN e || '{"precarga":"motivo"}'::JSONB ELSE e END ORDER BY ord)
                   FROM jsonb_array_elements(p.campos) WITH ORDINALITY AS t(e, ord))
 WHERE p.codigo IS NOT NULL AND p.tipo = 'visita'
   AND p.campos @> '[{"clave":"motivo"}]'::JSONB
   AND NOT p.campos @> '[{"clave":"motivo","precarga":"motivo"}]'::JSONB;
